 * @internal
 */
export function utf8ArrayToStr(
	array: Uint8Array,
	exitOnNull: boolean = false,
): string {
	const byteLength = exitOnNull ? array.indexOf(0) : array.length
	const view = new DataView(array.buffer, array.byteOffset, byteLength)
