export function arrayToHex(array: Uint8Array<ArrayBuffer> | number[]) {
  let str = '';
  for (let i = 0; i < array.length; i++) {
    let h = array[i].toString(16);
    if (h.length < 2) {
      h = '0' + h;
    }

    str += h;
  }
  return str;
}

export function hexToArrayBuffer(str: string): ArrayBuffer {
  return Uint8Array.from(
    str
      .replace(/^0x/, '')
      .replace(/([\da-fA-F]{2}) ?/g, '0x$1 ')
      .replace(/ +$/, '')
      .split(' '),
  ).buffer;
}
export function base64Decode(base64encodedStr: string) {
  return Uint8Array.from(atob(base64encodedStr), (c) => c.charCodeAt(0));
}

export function bin2str(data: number[] | Uint8Array | Uint16Array): string {
  return String.fromCharCode.apply(null, data);
}
